import { describe, expect, it } from 'vitest';
import { Injector } from '../../common/di';
import { FBlob } from '../f-blob';

describe('FBlob', () => {
    it('should copy, transform and read blob data through the injector', async () => {
        const injector = new Injector();
        const blob = injector.createInstance(FBlob, new Blob(['hello'], { type: 'text/plain' }));

        const copy = blob.copyBlob();
        const asJson = blob.getAs('application/json');

        expect(copy).not.toBe(blob);
        await expect(copy.getDataAsString()).resolves.toBe('hello');
        expect(asJson.getContentType()).toBe('application/json');
        await expect(asJson.getDataAsString()).resolves.toBe('hello');
        await expect(asJson.getBytes()).resolves.toEqual(new TextEncoder().encode('hello'));
    });

    it('should support byte and string setters plus charset decoding and null guards', async () => {
        const injector = new Injector();
        const blob = injector.createInstance(FBlob, null);

        await expect(blob.getDataAsString()).resolves.toBe('');
        await expect(blob.getBytes()).rejects.toThrow('Blob is undefined or null.');

        blob.setBytes(new Uint8Array([0xE9]));
        await expect(blob.getDataAsString('iso-8859-1')).resolves.toBe('é');

        blob.setDataFromString('payload', 'text/custom');
        expect(blob.getContentType()).toBe('text/custom');

        blob.setContentType('text/changed');
        expect(blob.getContentType()).toBe('text/changed');
        await expect(blob.getDataAsString()).resolves.toBe('payload');
    });
});

import * as React from 'react';
import { describe, it, expect, afterEach, beforeEach, vi } from 'vitest';
import { createRoot, type Root } from 'react-dom/client';
import { flushSync } from 'react-dom';
import Konva from 'konva';
import { Stage, Layer, Rect, Transformer } from '../src/ReactKonva';

(globalThis as any).IS_REACT_ACT_ENVIRONMENT = false;

const roots: { root: Root; container: HTMLElement }[] = [];
function mount(ui: React.ReactElement) {
  const container = document.createElement('div');
  document.body.appendChild(container);
  const root = createRoot(container);
  flushSync(() => root.render(ui));
  roots.push({ root, container });
}
let errors: ReturnType<typeof vi.spyOn>;
beforeEach(() => {
  errors = vi.spyOn(console, 'error');
});
afterEach(() => {
  while (roots.length) {
    const { root, container } = roots.pop()!;
    flushSync(() => root.unmount());
    container.remove();
  }
  const leaked = Konva.stages.length;
  [...Konva.stages].forEach((stage) => stage.destroy());
  const calls = errors.mock.calls;
  errors.mockRestore();
  expect(leaked, 'Stage cleanup').toBe(0);
  expect(calls, 'unexpected React errors').toEqual([]);
});

const raf = () => new Promise((r) => requestAnimationFrame(r));

// Transformer outline width as drawn: distance between corner anchors.
function outlineWidth(tr: Konva.Transformer) {
  const tl = tr.findOne('.top-left')!.getAbsolutePosition();
  const br = tr.findOne('.bottom-right')!.getAbsolutePosition();
  return br.x - tl.x;
}

function setupTransformBox(
  stateOwner: 'konva' | 'dom' = 'konva',
  normalizeImmediately = false,
) {
  let rectNode!: Konva.Rect;
  let trNode!: Konva.Transformer;
  let committedOutline = 0;
  let committedBox!: { x: number; y: number; width: number; height: number };
  const Box = () => {
    const [box, setBox] = React.useState({
      x: 80,
      y: 80,
      width: 160,
      height: 160,
    });
    React.useLayoutEffect(() => {
      committedBox = box;
      if (trRef.current?.isTransforming()) {
        committedOutline = trRef.current.findOne('.top-center')!.x() * 2;
      }
    });
    const rectRef = React.useRef<Konva.Rect>(null);
    const trRef = React.useRef<Konva.Transformer>(null);
    React.useLayoutEffect(() => {
      rectNode = rectRef.current!;
      trNode = trRef.current!;
      trRef.current!.nodes([rectRef.current!]);
    }, []);
    const shapes = (
      <>
        <Rect
          ref={rectRef}
          {...box}
          fill="tomato"
          onTransform={(e: any) => {
            // The standard react-konva transform pattern: bake scale into
            // state-driven width/height, reset scale on the node.
            const node = e.target;
            const sx = node.scaleX();
            const sy = node.scaleY();
            node.scaleX(1);
            node.scaleY(1);
            const next = {
              x: node.x(),
              y: node.y(),
              width: Math.max(5, node.width() * sx),
              height: Math.max(5, node.height() * sy),
            };
            if (normalizeImmediately) node.setAttrs(next);
            setBox(next);
          }}
        />
        <Transformer ref={trRef} keepRatio={false} rotateEnabled={false} />
      </>
    );
    return stateOwner === 'dom' ? (
      <Stage width={600} height={600}>
        <Layer>{shapes}</Layer>
      </Stage>
    ) : (
      shapes
    );
  };
  mount(
    stateOwner === 'dom' ? (
      <Box />
    ) : (
      <Stage width={600} height={600}>
        <Layer>
          <Box />
        </Layer>
      </Stage>
    ),
  );
  const stage = Konva.stages[Konva.stages.length - 1];

  // Start a real transform on the bottom-right anchor (Konva's own path:
  // anchor mousedown installs window mousemove/mouseup listeners).
  const anchor = trNode.findOne('.bottom-right')!;
  const crect = stage.content.getBoundingClientRect();
  const ap = anchor.getAbsolutePosition(); // (240, 240)
  const at = (dx: number, dy = 0) => ({
    clientX: ap.x + dx + crect.left,
    clientY: ap.y + dy + crect.top,
  });
  stage.setPointersPositions(at(0) as any);
  anchor.fire('mousedown', { evt: at(0) } as any);
  const move = (dx: number, dy = 0) =>
    window.dispatchEvent(new MouseEvent('mousemove', at(dx, dy)));
  const up = (dx: number) =>
    window.dispatchEvent(new MouseEvent('mouseup', at(dx)));

  return {
    rect: () => rectNode,
    tr: () => trNode,
    committed: () => committedBox,
    committedOutline: () => committedOutline,
    move,
    up,
  };
}

describe('Transformer with controlled state', () => {
  it('state above Stage settles before the next animation frame', async () => {
    const { rect, tr, move, up } = setupTransformBox('dom');
    try {
      move(40);
      await raf();
      expect(rect().width()).toBe(200);
      expect(outlineWidth(tr())).toBe(200);
      move(80);
      await raf();
      expect(rect().width()).toBe(240);
      expect(outlineWidth(tr())).toBe(240);
    } finally {
      up(80);
    }
  });

  it('state inside Stage also updates the Transformer before each frame', async () => {
    const { rect, tr, move, up } = setupTransformBox();
    try {
      // Frame 1: drag bottom-right +40px.
      move(40);
      await raf();
      expect(rect().width()).toBe(200);
      expect(outlineWidth(tr())).toBe(200);

      // Frame 2: +40 more. (Stale-read bug: outline lags one event behind.)
      move(80);
      await raf();
      expect(rect().width()).toBe(240);
      expect(outlineWidth(tr())).toBe(240);
    } finally {
      up(80);
    }
  });

  it('state above Stage keeps the outline current after React commits during a gesture', async () => {
    const { rect, tr, move, up } = setupTransformBox('dom');
    try {
      move(40);
      // Wait for React's normal commit without forcing it or imposing a frame
      // deadline. The outline must follow even while the gesture is active.
      await vi.waitFor(() => expect(rect().width()).toBe(200));
      expect(tr().isTransforming()).toBe(true);
      expect(outlineWidth(tr())).toBe(200);

      move(80);
      await vi.waitFor(() => expect(rect().width()).toBe(240));
      expect(outlineWidth(tr())).toBe(240);
    } finally {
      up(80);
    }
  });

  it('legacy timing: state inside Stage is visible immediately after the event', () => {
    // Preserve original §17.2: a complete native step commits before returning.
    const { rect, move, up } = setupTransformBox();
    try {
      move(40);
      expect(rect().width()).toBe(200);
      expect(rect().scaleX()).toBe(1);
    } finally {
      up(40);
    }
  });

  it.each(['dom', 'konva'] as const)(
    'immediate normalization keeps geometry correct with %s state',
    async (owner) => {
      const { rect, tr, committed, move, up } = setupTransformBox(owner, true);
      try {
        for (const [dx, dy] of [
          [40, 20],
          [80, 40],
        ]) {
          move(dx, dy);
          // Node geometry and anchors agree before React commits, then remain
          // correct when React records the same normalized dimensions.
          expect(rect().width()).toBeCloseTo(160 + dx);
          expect(rect().height()).toBeCloseTo(160 + dy);
          expect(rect().scaleX()).toBe(1);
          expect(rect().scaleY()).toBe(1);
          expect(outlineWidth(tr())).toBeCloseTo(160 + dx);
          await vi.waitFor(() => {
            expect(committed().width).toBeCloseTo(160 + dx);
            expect(committed().height).toBeCloseTo(160 + dy);
          });
          expect(rect().width()).toBeCloseTo(committed().width);
          expect(rect().height()).toBeCloseTo(committed().height);
          expect(outlineWidth(tr())).toBeCloseTo(committed().width);
          expect(tr().isTransforming()).toBe(true);
        }
      } finally {
        up(80);
      }
    },
  );
});

// A commit may update many selected nodes. Public geometry reads in attribute
// listeners and layout effects must remain fresh, even during a gesture.
it.each(['dom', 'konva'] as const)(
  'React commits expose fresh anchors to listeners and effects with %s state',
  (owner) => {
    const { rect, tr, move, up, committedOutline } = setupTransformBox(owner);
    let readInListener = 0;
    rect().on('widthChange.probe', () => {
      readInListener = tr().findOne('.top-center')!.x() * 2;
    });
    try {
      move(40);
      expect(rect().width()).toBe(200);
      expect(readInListener).toBe(200);
      expect(committedOutline()).toBe(200);
    } finally {
      up(40);
    }
  },
);

// §1 — Mounting / first-paint timing.
// Core invariant: by the time any DOM-side useLayoutEffect runs, the Konva tree
// of every mounted Stage is fully built.

import * as React from 'react';
import { describe, it, expect, vi } from 'vitest';
import Konva from 'konva';
import {
  Stage,
  Layer,
  Rect,
  Transformer,
} from '../src/ReactKonva';
import { render, act } from './helpers/render';

describe('§1 mounting / first-paint timing', () => {
  it('§1.1 single Stage parent useLayoutEffect can find Konva children (Transformer)', () => {
    let foundOnLayoutEffect: Konva.Node | null | undefined = undefined;
    const App = () => {
      const stageRef = React.useRef<Konva.Stage>(null);
      React.useLayoutEffect(() => {
        foundOnLayoutEffect = stageRef.current?.findOne('Transformer');
      });
      return (
        <Stage ref={stageRef} width={100} height={100}>
          <Layer>
            <Transformer />
          </Layer>
        </Stage>
      );
    };
    render(<App />);
    expect(foundOnLayoutEffect).toBeInstanceOf(Konva.Transformer);
  });

  it('§1.2 sibling Stages — each parent\'s useLayoutEffect finds its own stage\'s nodes', () => {
    const seen: Record<string, string | undefined> = {};
    const Slot = ({ id, fill }: { id: string; fill: string }) => {
      const stageRef = React.useRef<Konva.Stage>(null);
      React.useLayoutEffect(() => {
        const rect = stageRef.current?.findOne('Rect') as Konva.Rect | undefined;
        seen[id] = rect?.fill();
      });
      return (
        <Stage ref={stageRef} width={50} height={50}>
          <Layer>
            <Rect width={10} height={10} fill={fill} />
          </Layer>
        </Stage>
      );
    };
    render(
      <>
        <Slot id="a" fill="red" />
        <Slot id="b" fill="blue" />
      </>
    );
    expect(seen.a).toBe('red');
    expect(seen.b).toBe('blue');
  });

  it('§1.3 nested under a wrapping component — outer useLayoutEffect still sees Konva nodes', () => {
    let foundCount = -1;
    const Inner = () => (
      <Stage width={50} height={50}>
        <Layer>
          <Rect id="needle" width={10} height={10} />
        </Layer>
      </Stage>
    );
    const Outer = ({ children }: { children: React.ReactNode }) => {
      const ref = React.useRef<HTMLDivElement>(null);
      React.useLayoutEffect(() => {
        const stage = Konva.stages[Konva.stages.length - 1];
        foundCount = stage.find('#needle').length;
      });
      return <div ref={ref}>{children}</div>;
    };
    render(
      <Outer>
        <Inner />
      </Outer>
    );
    expect(foundCount).toBe(1);
  });

  it('§1.4 <Stage ref={...}> is set synchronously on mount — outer useLayoutEffect sees it', () => {
    let observed: Konva.Stage | null = null;
    const App = () => {
      const ref = React.useRef<Konva.Stage>(null);
      React.useLayoutEffect(() => {
        observed = ref.current;
      });
      return (
        <Stage ref={ref} width={100} height={100}>
          <Layer />
        </Stage>
      );
    };
    render(<App />);
    expect(observed).toBeInstanceOf(Konva.Stage);
  });

  it('§1.5 initial Konva node refs — child ref is a real Konva node before parent useLayoutEffect', () => {
    let observedRect: Konva.Rect | null = null;
    const App = () => {
      const rectRef = React.useRef<Konva.Rect>(null);
      React.useLayoutEffect(() => {
        observedRect = rectRef.current;
      });
      return (
        <Stage width={50} height={50}>
          <Layer>
            <Rect ref={rectRef} width={10} height={10} />
          </Layer>
        </Stage>
      );
    };
    render(<App />);
    expect(observedRect).toBeInstanceOf(Konva.Rect);
  });

  it('§1.6 Stage prop changes mid-life — applyNodeProps runs and node sees new value before next paint', () => {
    let observedWidthAfterUpdate = -1;
    const App = ({ width }: { width: number }) => {
      const stageRef = React.useRef<Konva.Stage>(null);
      React.useLayoutEffect(() => {
        observedWidthAfterUpdate = stageRef.current?.width() ?? -1;
      }, [width]);
      return (
        <Stage ref={stageRef} width={width} height={100}>
          <Layer />
        </Stage>
      );
    };
    const { rerender } = render(<App width={100} />);
    expect(observedWidthAfterUpdate).toBe(100);
    rerender(<App width={250} />);
    expect(observedWidthAfterUpdate).toBe(250);
  });

  it('§1.7 children added after first mount — parent useLayoutEffect (deps on count) sees the new node', () => {
    let observed = -1;
    const App = ({ count }: { count: number }) => {
      const stageRef = React.useRef<Konva.Stage>(null);
      React.useLayoutEffect(() => {
        observed = stageRef.current?.find('Rect').length ?? -1;
      }, [count]);
      return (
        <Stage ref={stageRef} width={100} height={100}>
          <Layer>
            {Array.from({ length: count }, (_, i) => (
              <Rect key={i} width={10} height={10} />
            ))}
          </Layer>
        </Stage>
      );
    };
    const { rerender } = render(<App count={1} />);
    expect(observed).toBe(1);
    rerender(<App count={3} />);
    expect(observed).toBe(3);
  });

  it('§1.8 keyed reorder with shrinking length — no leaks, correct z-order, instance identity preserved', () => {
    // Adapted from r3f's `'should properly handle array of components with
    // changing keys and order'`. Stresses placeChild/moveChild/removeChild
    // simultaneously. Konva Layer.children is paint-order, so a buggy
    // reorder silently regresses z-order without crashing.
    let setIds!: (xs: number[]) => void;
    const App = ({ ids }: { ids: number[] }) => (
      <Stage width={100} height={100}>
        <Layer>
          {ids.map((id) => (
            <Rect key={id} name={String(id)} width={10} height={10} />
          ))}
        </Layer>
      </Stage>
    );
    const Wrapper = () => {
      const [ids, set] = React.useState([1, 2, 3, 4]);
      setIds = set;
      return <App ids={ids} />;
    };
    const { stage } = render(<Wrapper />);
    const layer = stage()!.findOne('Layer') as Konva.Layer;
    const namesOf = () => layer.getChildren().map((c) => c.name());
    const idOf = (n: string) => (layer.findOne('.' + n) as Konva.Rect)._id;

    expect(namesOf()).toEqual(['1', '2', '3', '4']);
    const initialIds = { '1': idOf('1'), '2': idOf('2'), '3': idOf('3'), '4': idOf('4') };

    // Reorder + drop one.
    act(() => setIds([3, 1, 4]));
    expect(namesOf()).toEqual(['3', '1', '4']);
    // Same Konva.Rect instance per surviving key — proven by stable _id.
    expect(idOf('3')).toBe(initialIds['3']);
    expect(idOf('1')).toBe(initialIds['1']);
    expect(idOf('4')).toBe(initialIds['4']);
    expect(layer.findOne('.2')).toBeUndefined();
    expect(layer.getChildren().length).toBe(3);

    // Reorder + drop another.
    act(() => setIds([4, 1]));
    expect(namesOf()).toEqual(['4', '1']);
    expect(idOf('4')).toBe(initialIds['4']);
    expect(idOf('1')).toBe(initialIds['1']);
    expect(layer.findOne('.3')).toBeUndefined();
    expect(layer.getChildren().length).toBe(2);
  });

  it('§1.9 children removed after first mount — no zombie Konva node remains', () => {
    let observed = -1;
    const App = ({ count }: { count: number }) => {
      const stageRef = React.useRef<Konva.Stage>(null);
      React.useLayoutEffect(() => {
        observed = stageRef.current?.find('Rect').length ?? -1;
      }, [count]);
      return (
        <Stage ref={stageRef} width={100} height={100}>
          <Layer>
            {Array.from({ length: count }, (_, i) => (
              <Rect key={i} width={10} height={10} />
            ))}
          </Layer>
        </Stage>
      );
    };
    const { rerender, stage } = render(<App count={3} />);
    expect(observed).toBe(3);
    rerender(<App count={1} />);
    expect(observed).toBe(1);
    expect(stage()?.find('Rect').length).toBe(1);
  });

  it('§1.10 react-konva does not overwrite Konva-side prop changes from outside React', () => {
    // If user code mutates a Konva node imperatively (e.g. via drag),
    // a subsequent re-render with the same JSX prop must NOT overwrite that
    // imperative change. Toggled by `useStrictMode` (see §4) — this default
    // behavior is "preserve manual changes".
    const App = ({ x }: { x: number }) => (
      <Stage width={100} height={100}>
        <Layer>
          <Rect width={50} height={50} fill="red" x={x} />
        </Layer>
      </Stage>
    );
    const { rerender, stage } = render(<App x={10} />);
    const rect = stage()!.findOne('Rect') as Konva.Rect;
    expect(rect.x()).toBe(10);

    // Imperative mutation outside React.
    rect.x(20);

    // Re-render with the SAME JSX x={10} — react-konva must not clobber the 20.
    rerender(<App x={10} />);
    expect(rect.x()).toBe(20);
  });

  it('§1.11 Konva node ids persist across React re-renders (no remount)', () => {
    // Konva assigns each node an internal `_id`. After re-renders that don't
    // change keys, the same node instance must survive — so its `_id` is stable.
    const App = ({ x }: { x: number }) => (
      <Stage width={100} height={100}>
        <Layer>
          <Rect name="r" width={50} height={50} x={x} />
        </Layer>
      </Stage>
    );
    const { rerender, stage } = render(<App x={0} />);
    const initialId = (stage()!.findOne('.r') as Konva.Rect)._id;
    rerender(<App x={5} />);
    rerender(<App x={10} />);
    const laterId = (stage()!.findOne('.r') as Konva.Rect)._id;
    expect(laterId).toBe(initialId);
  });

  it('§1.12 Layer.batchDraw fires on mount', () => {
    const spy = vi.spyOn(Konva.Layer.prototype, 'batchDraw');
    try {
      render(
        <Stage width={50} height={50}>
          <Layer>
            <Rect width={10} height={10} fill="red" />
          </Layer>
        </Stage>
      );
      expect(spy).toHaveBeenCalled();
    } finally {
      spy.mockRestore();
    }
  });

  it('§1.13 Layer.batchDraw fires when a node is added', () => {
    const App = ({ show }: { show: boolean }) => (
      <Stage width={50} height={50}>
        <Layer>{show && <Rect width={10} height={10} fill="red" />}</Layer>
      </Stage>
    );
    const { rerender } = render(<App show={false} />);
    const spy = vi.spyOn(Konva.Layer.prototype, 'batchDraw');
    try {
      rerender(<App show={true} />);
      expect(spy).toHaveBeenCalled();
    } finally {
      spy.mockRestore();
    }
  });

  it('§1.14 Layer.batchDraw fires when a node is removed', () => {
    const App = ({ hide }: { hide: boolean }) => (
      <Stage width={50} height={50}>
        <Layer>{!hide && <Rect width={10} height={10} fill="red" />}</Layer>
      </Stage>
    );
    const { rerender } = render(<App hide={false} />);
    const spy = vi.spyOn(Konva.Layer.prototype, 'batchDraw');
    try {
      rerender(<App hide={true} />);
      expect(spy).toHaveBeenCalled();
    } finally {
      spy.mockRestore();
    }
  });
});

import { test } from 'node:test';
