import test from 'node:test';
import assert from 'node:assert/strict';

import { EventBus } from '../src/core/event-bus.ts';
import { DocumentDirtyState, type DirtyStateChange } from '../src/core/document-dirty-state.ts';

type Listener = (event: unknown) => unknown;

class FakeWindow {
  private listeners = new Map<string, Set<Listener>>();

  addEventListener(type: string, listener: Listener): void {
    if (!this.listeners.has(type)) {
      this.listeners.set(type, new Set());
    }
    this.listeners.get(type)!.add(listener);
  }

  removeEventListener(type: string, listener: Listener): void {
    this.listeners.get(type)?.delete(listener);
  }

  dispatch(type: string, event: unknown): void {
    for (const listener of this.listeners.get(type) ?? []) {
      listener(event);
    }
  }

  listenerCount(type: string): number {
    return this.listeners.get(type)?.size ?? 0;
  }
}

function createBeforeUnloadEvent() {
  return {
    defaultPrevented: false,
    returnValue: undefined as string | undefined,
    preventDefault() {
      this.defaultPrevented = true;
    },
  };
}

test('DocumentDirtyState는 dirty/clean 전환 시 변경 이벤트를 한 번씩 발행한다', () => {
  const eventBus = new EventBus();
  const changes: DirtyStateChange[] = [];
  eventBus.on('document-dirty-changed', (payload) => changes.push(payload as DirtyStateChange));

  const state = new DocumentDirtyState(eventBus);

  assert.equal(state.isDirty(), false);

  state.markDirty('typing');
  state.markDirty('typing-again');
  state.markClean('save');
  state.markClean('save-again');

  assert.deepEqual(changes, [
    { dirty: true, reason: 'typing' },
    { dirty: false, reason: 'save' },
  ]);
  assert.equal(state.isDirty(), false);
});

test('DocumentDirtyState beforeunload는 dirty 상태에서만 페이지 이탈을 막는다', () => {
  const state = new DocumentDirtyState(new EventBus());
  const fakeWindow = new FakeWindow();

  state.installBeforeUnload(fakeWindow as unknown as Window);

  const cleanEvent = createBeforeUnloadEvent();
  fakeWindow.dispatch('beforeunload', cleanEvent);
  assert.equal(cleanEvent.defaultPrevented, false);
  assert.equal(cleanEvent.returnValue, undefined);

  state.markDirty('typing');
  const dirtyEvent = createBeforeUnloadEvent();
  fakeWindow.dispatch('beforeunload', dirtyEvent);
  assert.equal(dirtyEvent.defaultPrevented, true);
  assert.equal(dirtyEvent.returnValue, '');

  state.markClean('save');
  const savedEvent = createBeforeUnloadEvent();
  fakeWindow.dispatch('beforeunload', savedEvent);
  assert.equal(savedEvent.defaultPrevented, false);
  assert.equal(savedEvent.returnValue, undefined);
});

test('DocumentDirtyState beforeunload 해제 함수는 설치한 핸들러만 제거한다', () => {
  const state = new DocumentDirtyState(new EventBus());
  const fakeWindow = new FakeWindow();

  const uninstall = state.installBeforeUnload(fakeWindow as unknown as Window);
  assert.equal(fakeWindow.listenerCount('beforeunload'), 1);

  uninstall();
  assert.equal(fakeWindow.listenerCount('beforeunload'), 0);

  state.markDirty('typing');
  const event = createBeforeUnloadEvent();
  fakeWindow.dispatch('beforeunload', event);
  assert.equal(event.defaultPrevented, false);
});

import { describe, expect, it } from 'vitest'
import { verifyAngularDevelopmentAssetModes } from '../apps/component-demo/scripts/lib/angular-asset-modes.mjs'

describe('Angular asset fixture server isolation', () => {
  it.each(['none', 'development', 'development-restart', 'second-start'])(
    'starts every development verification with an intact staged-asset fixture after %s',
    async (failure) => {
      const events: string[] = []
      let running = false
      let starts = 0
      const verification = verifyAngularDevelopmentAssetModes({
        start: async () => {
          expect(running).toBe(false)
          running = true
          starts += 1
          events.push(`start:${starts}`)
          if (starts === 2 && failure === 'second-start') throw new Error(failure)
          return 4000 + starts
        },
        stop: async () => {
          expect(running).toBe(true)
          events.push('stop')
          running = false
        },
        verify: async (mode: string, port: number) => {
          events.push(mode)
          expect(running).toBe(true)
          expect(port).toBe(4000 + starts)
          if (mode === failure) throw new Error(failure)
        }
      })
      if (failure === 'none') await verification
      else await expect(verification).rejects.toThrow(failure)
      expect(running).toBe(false)
      expect(events).toEqual([
        'start:1',
        'development',
        'stop',
        ...(failure === 'development'
          ? []
          : ['start:2', ...(failure === 'second-start' ? [] : ['development-restart']), 'stop'])
      ])
    }
  )
})

import { describe, expect, it } from 'vitest'
import { parseHTML } from 'linkedom'
import { createFileViewerCadExportAdapter } from '../packages/renderers/cad/src/export'
import { applyCadViewerColorMode, resolveFileViewerCadCanvasOptions } from '../packages/renderers/cad/src/colorMode'

describe('CAD view and portable output', () => {
  it('pairs authored colors with a dark canvas and monochrome with white paper', () => {
    expect(resolveFileViewerCadCanvasOptions({}, 'source').background).toBe('#05070d')
    expect(resolveFileViewerCadCanvasOptions({}, 'monochrome').background).toBe('#ffffff')
    const options = { canvasOptions: { background: '#123456' }, dwfBackground: '#abcdef' }
    expect(resolveFileViewerCadCanvasOptions(options, 'monochrome').background).toBe('#123456')
    const calls: unknown[] = []
    applyCadViewerColorMode({
      setColorMode: (...args) => calls.push(args),
      isNativeRendererActive: () => true,
      setCanvasOptions: options => calls.push(options.background)
    }, 'monochrome', '#000000', options)
    expect(calls).toEqual([['monochrome', '#000000'], '#abcdef'])
  })

  it('exports the engine snapshot rather than a cleared WebGL canvas or live controls', async () => {
    const { document } = parseHTML('<html><body></body></html>')
    const snapshot = { ownerDocument: document, width: 800, height: 600, toDataURL: () => 'data:image/png;base64,c25hcHNob3Q=' }
    const viewer = { captureCanvas: async () => snapshot as unknown as HTMLCanvasElement }
    const adapter = createFileViewerCadExportAdapter(() => viewer, 'drawing"<.dxf')
    const html = await adapter.toHtml!({ mode: 'export' } as any)
    const image = parseHTML(`<html><body>${html}</body></html>`).document.querySelector('img')!
    expect(image.getAttribute('src')).toBe('data:image/png;base64,c25hcHNob3Q=')
    expect(image.getAttribute('alt')).toBe('drawing"<.dxf')
    expect(image.getAttribute('width')).toBe('800')
    expect(image.parentElement?.getAttribute('data-viewer-print-page-index')).toBe('0')
    expect(html).not.toContain('canvas')
  })

  it('scopes print masks to the live drawing rather than sidebars and toolbars', () => {
    const { document } = parseHTML('<html><body><div id="stage"></div></body></html>')
    const page = document.getElementById('stage')!
    const adapter = createFileViewerCadExportAdapter(() => null, 'drawing.dxf', () => page)
    expect(adapter.getPrintMaskPages?.()).toEqual([page])
    expect(adapter.includeDocumentStyles).toBe(false)
  })

  it('refuses a stale capture after the user changes or closes the document', async () => {
    let current: any
    current = { captureCanvas: async () => { current = null; return {} as HTMLCanvasElement } }
    const adapter = createFileViewerCadExportAdapter(() => current)
    await expect(adapter.toHtml!({ mode: 'print' })).rejects.toThrow('changed during export')
  })
})

